package org.example;

public class App {
    public String getGreeting() {
        return "Hello World!";
    }

    public static void main(String[] args) {
         Account myaccount = new Account("DE 123...");
         System.out.println(myaccount);
        try {
           myaccount.withdraw(-10); 
        } catch (AccountOverdrawnException | InvalidAmountException e){
            //Behandlung der ausgabe
            System.out.println(e.getMessage()); 
        } 
        //Hier geht es weiter!!!
        System.out.println("weiter gehts");
        System.out.println(myaccount);

        
    }
}
